import{_ as o,o as a,c as n,ah as r}from"./chunks/framework.BK78naE0.js";const s="/projects/JetMaxPro/en/latest/assets/image2.C_Bmzt5t.webp",i="/projects/JetMaxPro/en/latest/assets/image3.BOng6fXf.webp",l="data:image/png;base64,",c="/projects/JetMaxPro/en/latest/assets/image5.CA216DsL.webp",g="/projects/JetMaxPro/en/latest/assets/image6.D4bVg6fe.webp",p="/projects/JetMaxPro/en/latest/assets/image7.D8HIceji.webp",m="/projects/JetMaxPro/en/latest/assets/image2.cMMNUvrM.webp",d="/projects/JetMaxPro/en/latest/assets/image2.Ds_0-uHK.webp",h="/projects/JetMaxPro/en/latest/assets/image3.9dmm2c5Z.webp",u="/projects/JetMaxPro/en/latest/assets/image4.BqF9xdlH.webp",f="/projects/JetMaxPro/en/latest/assets/image5.BNrdl4Wb.webp",b="/projects/JetMaxPro/en/latest/assets/image3.C5abTGUy.webp",y="/projects/JetMaxPro/en/latest/assets/image7.fb-IniTc.webp",w="/projects/JetMaxPro/en/latest/assets/image8.htMWCM8S.webp",x="/projects/JetMaxPro/en/latest/assets/image9.TMkhflZd.webp",A="/projects/JetMaxPro/en/latest/assets/image10.CEXjKi1b.webp",P="/projects/JetMaxPro/en/latest/assets/image11.CjKi5_mH.webp",v="data:image/png;base64,",_="/projects/JetMaxPro/en/latest/assets/image13.BchzOojP.webp",J="/projects/JetMaxPro/en/latest/assets/image14.DTMaQaHs.webp",C="/projects/JetMaxPro/en/latest/assets/image15.IQNo3OjR.webp",z="/projects/JetMaxPro/en/latest/assets/image16.B3XwWyD5.webp",T="/projects/JetMaxPro/en/latest/assets/image17.B5OnRVa7.webp",S="/projects/JetMaxPro/en/latest/assets/image18.B3id4IVR.webp",j="/projects/JetMaxPro/en/latest/assets/image19.DiGL3665.webp",O="/projects/JetMaxPro/en/latest/assets/image18.qu0c_BI4.webp",q="/projects/JetMaxPro/en/latest/assets/image19.D6Xif9-F.webp",M="/projects/JetMaxPro/en/latest/assets/image20.TADCR7mC.webp",R="/projects/JetMaxPro/en/latest/assets/image21.iRuo1xQ5.webp",I="/projects/JetMaxPro/en/latest/assets/image22.DJlEBvjX.webp",k="/projects/JetMaxPro/en/latest/assets/image23.BiDkkJBl.webp",Q="/projects/JetMaxPro/en/latest/assets/image24.CJtpKRTd.webp",X="/projects/JetMaxPro/en/latest/assets/image25.CJperPfO.webp",D="/projects/JetMaxPro/en/latest/assets/image28.DsAYStA0.webp",B="/projects/JetMaxPro/en/latest/assets/image2.BO4Y__Il.webp",E="/projects/JetMaxPro/en/latest/assets/image3.9dmm2c5Z.webp",e="/projects/JetMaxPro/en/latest/assets/image4.BqF9xdlH.webp",U="/projects/JetMaxPro/en/latest/assets/image5.BNrdl4Wb.webp",K="/projects/JetMaxPro/en/latest/assets/image3.C5abTGUy.webp",V="/projects/JetMaxPro/en/latest/assets/image7.fb-IniTc.webp",L="/projects/JetMaxPro/en/latest/assets/image8.htMWCM8S.webp",Y="/projects/JetMaxPro/en/latest/assets/image9.B8FFtuyq.webp",G="/projects/JetMaxPro/en/latest/assets/image10.CEXjKi1b.webp",W="/projects/JetMaxPro/en/latest/assets/image11.hxducmwg.webp",F="data:image/png;base64,",H="data:image/png;base64,",N="/projects/JetMaxPro/en/latest/assets/image14.D-S2dfQL.webp",Z="/projects/JetMaxPro/en/latest/assets/image15.Duo4Oefi.webp",$="/projects/JetMaxPro/en/latest/assets/image16.BSEFzfia.webp",tt="/projects/JetMaxPro/en/latest/assets/image17.CN5-s4My.webp",et="/projects/JetMaxPro/en/latest/assets/image14.DTMaQaHs.webp",ot="/projects/JetMaxPro/en/latest/assets/image16.B3XwWyD5.webp",at="/projects/JetMaxPro/en/latest/assets/image17.B5OnRVa7.webp",nt="/projects/JetMaxPro/en/latest/assets/image18.B3id4IVR.webp",rt="/projects/JetMaxPro/en/latest/assets/image19.DiGL3665.webp",st="/projects/JetMaxPro/en/latest/assets/image23.CIuRk_rR.webp",it="/projects/JetMaxPro/en/latest/assets/image24.C-96JUXM.webp",lt="/projects/JetMaxPro/en/latest/assets/image25.CbzwHSnJ.webp",ct="/projects/JetMaxPro/en/latest/assets/image14.CXAZE-iv.webp",gt="/projects/JetMaxPro/en/latest/assets/image15.0IxfC5yr.webp",pt="/projects/JetMaxPro/en/latest/assets/image28.BbnjJm6x.webp",xt=JSON.parse('{"title":"16. Robot Arm + Sliding Rail Lesson","description":"","frontmatter":{},"headers":[],"relativePath":"docs/16.Robot Arm + Sliding Rail Lesson.md","filePath":"docs/16.Robot Arm + Sliding Rail Lesson.md"}'),mt={name:"docs/16.Robot Arm + Sliding Rail Lesson.md"};function dt(ht,t,ut,ft,bt,yt){return a(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="_16-robot-arm-sliding-rail-lesson" tabindex="-1">16. Robot Arm + Sliding Rail Lesson <a class="header-anchor" href="#_16-robot-arm-sliding-rail-lesson" aria-label="Permalink to &quot;16. Robot Arm + Sliding Rail Lesson&quot;">​</a></h1><h2 id="_16-1-lesson-2-position-calibration" tabindex="-1">16.1 Lesson 2 Position Calibration <a class="header-anchor" href="#_16-1-lesson-2-position-calibration" aria-label="Permalink to &quot;16.1 Lesson 2 Position Calibration&quot;">​</a></h2><p>The purpose of position calibration is to convert robot arm’s coordinate on the phone to its real position. After position calibration, JetMax pro can better pick and sort objects.</p><p><strong>Note: this lesson is exclusive to JetMax Pro. You need to install robot arm on sliding rail before operation. Please strictly follow instructions below and do not skip any step.</strong></p><ol><li>Install and connect to WonderAi APP according to ‘<strong>1. Getting Ready&gt;Lesson 6 APP Control</strong>’. Then tap robotic icon, and select ‘<strong>position calibration</strong>’.</li></ol><img loading="lazy" height="613" width="1264" class="common_img" src="'+s+'" style="width:800px;" alt="G:\\gongzuo\\JetMax\\外贸版本\\手机APP试玩\\已处理\\Screenshot_20211027_103832_com.hiwonder.wonder_ai.jpgScreenshot_20211027_103832_com.hiwonder.wonder_ai"><img loading="lazy" height="614" width="1264" class="common_img" src="'+i+'" style="width:800px;" alt="G:\\gongzuo\\JetMax\\外贸版本\\手机APP试玩\\已处理\\Screenshot_20211027_103837_com.hiwonder.wonder_ai.jpgScreenshot_20211027_103837_com.hiwonder.wonder_ai"><ol start="2"><li>It is normal that the image transmitted by camera delays for a few seconds. If still no image occurs after a long time, return back to home interface, then tap <img loading="lazy" height="31" width="34" class="inline-icon" src="'+l+'"> and enter this interface again. Once camera returned image appears, tap ’<strong>Start position calibration</strong>’</li></ol><img loading="lazy" height="583" width="1263" class="common_img" src="'+c+'" style="width:800px;" alt="G:\\gongzuo\\JetMax\\外贸版本\\手机APP试玩\\已处理\\Screenshot_20211027_121101_com.hiwonder.wonder_ai.jpgScreenshot_20211027_121101_com.hiwonder.wonder_ai"><ol start="3"><li><p>Place Tag block directly under the suction nozzle following the hints. Only if the suction nozzle is at the center of the block when the robotic arm bends down, you can click “<strong>Next</strong>”.</p><p><strong>Note: tag block is not fixed to the dotted box. It can be placed outside the dotted box.</strong></p></li></ol><img loading="lazy" height="583" width="1264" class="common_img" src="'+g+'" style="width:800px;" alt="G:\\gongzuo\\JetMax\\外贸版本\\手机APP试玩\\已处理\\Screenshot_20211027_121114_com.hiwonder.wonder_ai.jpgScreenshot_20211027_121114_com.hiwonder.wonder_ai"><ol start="4"><li>When 5 black dots on the screen coincide with 5 colored dots on the AprilTag block, please tap “<strong>Complete</strong>”.</li></ol><img loading="lazy" height="614" width="1263" class="common_img" src="'+p+'" style="width:800px;" alt="C:\\Users\\Admin\\Desktop\\1.jpg1"><h2 id="_16-2-lesson-3-handle-control" tabindex="-1">16.2 Lesson 3 Handle Control <a class="header-anchor" href="#_16-2-lesson-3-handle-control" aria-label="Permalink to &quot;16.2 Lesson 3 Handle Control&quot;">​</a></h2><p>Step 1: insert the handle receiver to any USB port on Jetson Nano.</p><p><strong>Note: please insert the handle receiver before starting the robot.</strong></p><p>Step2: prepare two AAA batteries. Then insert them to battery slot. Please don’t invert ‘+’ and ‘-’ poles.</p><img loading="lazy" height="482" width="1288" class="common_img" src="'+m+'" style="width:800px;" alt="C:/Users/ADMINI~1/AppData/Local/Temp/picturescale_20200424200056/output_20200424200058.pngoutput_20200424200058"><h3 id="_16-2-1-device-connection" tabindex="-1">16.2.1 Device Connection <a class="header-anchor" href="#_16-2-1-device-connection" aria-label="Permalink to &quot;16.2.1 Device Connection&quot;">​</a></h3><p>Step 1: start JetMax Pro</p><p>Step 2: turn on handle. At this time, two LED lights on it will flash at the same time.</p><p>Step 3: wait for a few seconds. JetMax Pro automatically matches with the handle. Green LED light will be on once they match successfully.</p><p>If handle does not connect to the robot within 30 seconds after turned on, or there is no operation on handle within 5 minutes after connection, handle will enter sleep mode. If you want to wake it up, press “<strong>START</strong>” key.</p><h3 id="_16-2-2-introduction-to-mode" tabindex="-1">16.2.2 Introduction to Mode <a class="header-anchor" href="#_16-2-2-introduction-to-mode" aria-label="Permalink to &quot;16.2.2 Introduction to Mode&quot;">​</a></h3><p>There are two control modes, namely coordinate mode and individual servo mode. Handle enters individual servo mode by default after connection.</p><p>Individual servo mode: you can control servo separately on robot arm to rotate.</p><p>Coordinate mode: you can control robot arm to move in the direction of X, Y, Z axes.</p><p>Way to switch mode: press “<strong>SELECT</strong>” key. When handle emits sound, it means the mode is successfully switched. When sounding once, it is switched to coordinate mode. When sounding twice, it is switched to individual servo mode.</p><h3 id="_16-2-3-key-function" tabindex="-1">16.2.3 Key Function <a class="header-anchor" href="#_16-2-3-key-function" aria-label="Permalink to &quot;16.2.3 Key Function&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Key</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;">START</td><td style="text-align:center;">Reset robot arm and sliding rail</td></tr><tr><td style="text-align:center;">SELECT</td><td style="text-align:center;">Switch control mode(servo/ coordinate)</td></tr><tr><td style="text-align:center;">↑</td><td style="text-align:center;">NO.2 servo rotates inversely/ robot arm moves in the direction of negative Y axis</td></tr><tr><td style="text-align:center;">↓</td><td style="text-align:center;">NO.2 servo rotates forward/ robot arm moves in the direction of positive Y axis</td></tr><tr><td style="text-align:center;">←</td><td style="text-align:center;">NO.1 servo rotates forward/ robot arm moves in the direction of positive X axis</td></tr><tr><td style="text-align:center;">→</td><td style="text-align:center;">NO.1 servo rotates inversely/ robot arm moves in the direction of negative X axis</td></tr><tr><td style="text-align:center;">TRIANGLE / ∆</td><td style="text-align:center;">NO.3 servo rotates inversely/ robot arm moves in the direction of positive Z axis</td></tr><tr><td style="text-align:center;">CROSS / X</td><td style="text-align:center;">NO.3 servo rotates forward/ robot arm moves in the direction of negative Z axis</td></tr><tr><td style="text-align:center;">CIRCLE / ⃝</td><td style="text-align:center;">suction nozzle rotates clockwise</td></tr><tr><td style="text-align:center;">SQUARE / ◻</td><td style="text-align:center;">suction nozzle rotates counterclockwise</td></tr><tr><td style="text-align:center;">L2</td><td style="text-align:center;">Turn on air pump</td></tr><tr><td style="text-align:center;">R2</td><td style="text-align:center;">Turn off air pump</td></tr><tr><td style="text-align:center;">L1</td><td style="text-align:center;">Sliding rail slides to left</td></tr><tr><td style="text-align:center;">R1</td><td style="text-align:center;">Sliding rail slides to right</td></tr></tbody></table><h2 id="_16-3-lesson-4-waste-sorting" tabindex="-1">16.3 Lesson 4 Waste Sorting <a class="header-anchor" href="#_16-3-lesson-4-waste-sorting" aria-label="Permalink to &quot;16.3 Lesson 4 Waste Sorting&quot;">​</a></h2><p>The program sorts the waste cards based on the trained yolov5 model. Then control robot arm to suck cards and place them to specific position.</p><p><strong>Step 1: Recognize and Sort</strong></p><p>Firstly, subscribe to real-time image data published by camera node, then convert it to Numpy format. After conversion, transfer the image to yolov5 network to perform operations such as scaling, transposing, and array expansion so as to obtain processing results.</p><p>Convert the coordinate of the obtained waste cards into the coordinate of the original image. After the coordinate is converted, sort the waste according to the recognized waste name and the set rules, and get the corresponding waste category. Then, frame the waste and print its name and recognition confidence.</p><p><strong>Step 2: Suck and Place</strong></p><p>To ensure the credibility of the result, recognize the object for multiple times. After the target is confirmed, control robot arm to sort and transfer, and convert the pixel coordinate of the target card into world coordinate.</p><p>Calculate the angle between robot arm and central axis, and control suction nozzle to rotate to corresponding angle. Then control robot arm to move to the position where the card is placed, and let it suck the card. Next, set the sliding time of robot arm on the sliding rail according to the waste category to let robot arm slides to the position where the waste card of specific category should be placed, and put down the card.</p><p>The source code of this program is stored in</p><p><strong>/ros/src/stepper/scripts/waste_classification_stepper.py</strong></p><img loading="lazy" height="848" width="1666" class="common_img" src="'+d+'" style="width:800px;"><h3 id="_16-3-1-operation-steps" tabindex="-1">16.3.1 Operation Steps <a class="header-anchor" href="#_16-3-1-operation-steps" aria-label="Permalink to &quot;16.3.1 Operation Steps&quot;">​</a></h3><ol><li><p>Start JetMax Pro, and connect your computer to WiFi generated by JetMax Pro.</p><img loading="lazy" height="234" width="359" class="common_img" src="'+h+'" style="width:800px;"></li><li><p>Connect to robot system desktop through NoMachine. Double click <img loading="lazy" height="91" width="81" class="inline-icon" src="'+u+'" alt="terminal"> to open terminal. (For how to install and use NoMachine, please refer to ‘<strong>7. Robot System Remote Connection</strong>’.) Robot system is as pictured.</p><img loading="lazy" height="671" width="1267" class="common_img" src="'+f+'" style="width:800px;"></li><li><p>Click <img loading="lazy" height="66" width="69" class="inline-icon" src="'+b+'"> or press “<strong>Ctrl+Alt+T</strong>” to open terminal.</p></li><li><p>Input command ‘<strong>cd ros/src/stepper/scripts/</strong>’ and press Enter to go to the directory where the game program is stored.</p><img loading="lazy" height="26" width="554" class="common_img" src="'+y+'" style="width:600px;"></li><li><p>Input command ‘<strong>./kill_app_funcs.sh</strong>’ and press Enter to close APP auto-start service.</p><img loading="lazy" height="22" width="633" class="common_img" src="'+w+'" style="width:600px;"></li><li><p>Input command “<strong>rosrun stepper waste_classification_stepper.py</strong>” to start fingertips control. It takes about 30s to start the game. Please be patient!</p><img loading="lazy" height="37" width="725" class="common_img" src="'+x+'" style="width:600px;"></li><li><p>Input command “<strong>./restart_app_funcs.sh</strong>” to enable APP service. Do not skip this step, otherwise other games will be influenced.</p><img loading="lazy" height="21" width="645" class="common_img" src="'+A+'" style="width:600px;"></li></ol><h3 id="_16-3-2-program-outcome" tabindex="-1">16.3.2 Program Outcome <a class="header-anchor" href="#_16-3-2-program-outcome" aria-label="Permalink to &quot;16.3.2 Program Outcome&quot;">​</a></h3><p>After the game starts, place the waste card within the recognition area on the map. Robot arm will place cards to specific area according to sorting result.</p><h3 id="_16-3-3-program-analysis" tabindex="-1">16.3.3 Program Analysis <a class="header-anchor" href="#_16-3-3-program-analysis" aria-label="Permalink to &quot;16.3.3 Program Analysis&quot;">​</a></h3><h3 id="import-function-library" tabindex="-1">Import Function Library <a class="header-anchor" href="#import-function-library" aria-label="Permalink to &quot;Import Function Library&quot;">​</a></h3><img loading="lazy" height="420" width="967" class="common_img" src="'+P+'" style="width:800px;"><h3 id="import-opencv-time-mathematics-thread-and-inverse-kinematics-libraries-you-can-call-functions-in-the-library-in-this-format-library-name-function-name-parameter-parameter" tabindex="-1">Import OpenCV, time, mathematics, thread and inverse kinematics libraries. You can call functions in the library in this format, ‘library name + function name(parameter,parameter...)’.<img loading="lazy" height="42" width="637" class="inline-icon" src="'+v+'"> <a class="header-anchor" href="#import-opencv-time-mathematics-thread-and-inverse-kinematics-libraries-you-can-call-functions-in-the-library-in-this-format-library-name-function-name-parameter-parameter" aria-label="Permalink to &quot;Import OpenCV, time, mathematics, thread and inverse kinematics libraries. You can call functions in the library in this format, ‘library name + function name(parameter,parameter...)’.&lt;img loading=&quot;lazy&quot; height=&quot;42&quot; width=&quot;637&quot; class=&quot;inline-icon&quot; src=&quot;../_static/media/chapter_16/section_3_0/media/image12.png&quot;  /&gt;&quot;">​</a></h3><p>time.sleep (0.01) means that ‘<strong>sleep</strong>’ function in ‘<strong>time</strong>’ library is called. The function of sleep() is to delay.</p><p>There are some built-in libraries in Python, such as ‘<strong>time</strong>’, ‘<strong>cv2</strong>’ and ‘<strong>math</strong>’, and you can directly import and call the library. Or you can write a library on your own.</p><p>‘<strong>std_srvs.srv</strong>’ is a library of ros service type.</p><h3 id="define-global-variables" tabindex="-1">Define Global Variables <a class="header-anchor" href="#define-global-variables" aria-label="Permalink to &quot;Define Global Variables&quot;">​</a></h3><p>The analysis of following code is divided into three parts.</p><p>First part:</p><p>Set the name of node, import the storage path of the model and input the size of picture.</p><p>Second part:</p><p>Set the object to be recognized, and the quantity of the object to be recognized. Lastly, set the type of object.</p><p>Third part</p><p>Set different colors corresponding to different categories, and the position where cards are stored.</p><img loading="lazy" height="630" width="1236" class="common_img" src="'+_+'" style="width:800px;"><p><strong>4.3 Convert Camera Coordinate to Real Coordinate</strong></p><img loading="lazy" height="757" width="1630" class="common_img" src="'+J+'" style="width:800px;"><p><strong>camer_to_world</strong> function is used to convert the coordinate on camera to real coordinate so as to get the real distance. The meaning of parameters of this function is as below.</p><p>Cam_mtx：</p><p>Transfer <strong>Cam_mtx</strong> to <strong>np.asmatrix.I</strong> function to get inverse matrix <strong>inv_k</strong> of cam_mtx</p><p>r：</p><p>Use <strong>np.zeros</strong> function to create empty matrix <strong>r_mat</strong>. Input <strong>r</strong> to <strong>cv2.Rodrigues</strong> function to convert vector to matrix and fill in <strong>r_mat</strong>. Then input <strong>r_mat</strong> into the <strong>np.asmatrix.I</strong> function to get the inverse matrix <strong>inv_r</strong> of <strong>r_mat</strong>.</p><p>t：</p><p>Input t into <strong>np.asmatrix</strong> to get new matrix, and input this new matrix and matrix <strong>inv_r</strong> into <strong>np.dot</strong> so as to compute the matrix <strong>transPlaneToCam</strong> required to convert coordinate.</p><p>Define the list <strong>world_pt = []</strong> used for output</p><p>Define a new matrix <strong>coords</strong></p><p>Define cyclic reading <strong>img_points</strong>, and name the content read each time <strong>img_pt</strong>, and put <strong>img_pt</strong> into corresponding empty matrix <strong>coords</strong>.</p><p>Use <strong>coords</strong> and <strong>inv_k</strong> to compute new matrix <strong>worldPtCam</strong>. Divide <strong>transPlaneToCam</strong> and <strong>worldPtCam</strong> to get the transformation coefficient <strong>scale</strong>.</p><p><strong>scale</strong> times <strong>worldPtPlane</strong> to get the transformed matrix <strong>scale_worldPtPlane</strong>.</p><p><strong>scale_worldPtPlane</strong> matrix subtracts <strong>transPlaneToCam</strong> matrix to get real coordinate <strong>worldPtPlaneReproject</strong>.</p><p>Define an empty matrix <strong>pt</strong> used to store coordinate, and assign the value of <strong>worldPtPlaneReproject</strong> to <strong>pt</strong>. Lastly, add <strong>pt</strong> to <strong>world_pt</strong>.</p><p><strong>4.4 Apriltag Sorting</strong></p><p>WasteClassifiction can be divided into three parts, namely definition, reset and camera parameter reading. In the first part, define some basic parameters that are required, and some threads that can be called repetitively. In the second part, reset a part of basic parameters. In the third part, read camera parameter and fill them in basic parameters.</p><img loading="lazy" height="694" width="1219" class="common_img" src="'+C+'" style="width:800px;"><h3 id="analyze-main-function" tabindex="-1">Analyze Main Function <a class="header-anchor" href="#analyze-main-function" aria-label="Permalink to &quot;Analyze Main Function&quot;">​</a></h3><p>In python, ‘<strong>__name__ == ’__main__:’</strong>’ is main function of the program. The program firstly call rospy.init_node() function, and initialize node with ros. Initialization configuration includes ports, external devices, and timed interrupts, which are completed during initialization.</p><img loading="lazy" height="413" width="1268" class="common_img" src="'+z+'" style="width:600px;"><p>Robot arm and sliding rail recover initial position. Set sliding rail mode.</p><img loading="lazy" height="207" width="863" class="common_img" src="'+T+'" style="width:800px;"><h4 id="instantiate" tabindex="-1">Instantiate <a class="header-anchor" href="#instantiate" aria-label="Permalink to &quot;Instantiate&quot;">​</a></h4><img loading="lazy" height="230" width="1039" class="common_img" src="'+S+'" style="width:800px;"><p>As names of some function libraries are too long, you can instantiate the function library making it convenient to call functions. After instantiation, you can directly call function in this way, ‘jetmax.function name(parameter, parameter...)’</p><h4 id="publish-and-subscribe-to-topic" tabindex="-1">Publish and Subscribe to Topic <a class="header-anchor" href="#publish-and-subscribe-to-topic" aria-label="Permalink to &quot;Publish and Subscribe to Topic&quot;">​</a></h4><p>Subscribe to function that processes image</p><img loading="lazy" height="100" width="1788" class="common_img" src="'+j+'" style="width:600px;"><h3 id="process-and-analyze-image" tabindex="-1">Process and Analyze Image <a class="header-anchor" href="#process-and-analyze-image" aria-label="Permalink to &quot;Process and Analyze Image&quot;">​</a></h3><img loading="lazy" height="922" width="1916" class="common_img" src="'+O+'" style="width:800px;"><h4 id="get-image" tabindex="-1">Get Image <a class="header-anchor" href="#get-image" aria-label="Permalink to &quot;Get Image&quot;">​</a></h4><p>Get the latest image to determine whether JetMax Pro is transferring object. If it is, the program will directly return, then obtain latest picture in loop.</p><img loading="lazy" height="249" width="1414" class="common_img" src="'+q+'" style="width:800px;"><h4 id="recognize-image" tabindex="-1">Recognize Image <a class="header-anchor" href="#recognize-image" aria-label="Permalink to &quot;Recognize Image&quot;">​</a></h4><p>Convert ros image into OpenCV image, then use yolov5 trained model to recognize image. The recognition result is output to ‘<strong>boxes</strong>’, ‘<strong>confs</strong>’ and ‘<strong>classes</strong>’.</p><p>‘<strong>width</strong>’ and ‘<strong>height</strong>’ are the dimension of the image</p><img loading="lazy" height="366" width="1830" class="common_img" src="'+M+'" style="width:800px;"><h4 id="process-image-information" tabindex="-1">Process Image Information <a class="header-anchor" href="#process-image-information" aria-label="Permalink to &quot;Process Image Information&quot;">​</a></h4><p>Map the result to the coordinate of the original image to obtain waste name and waste category.</p><img loading="lazy" height="416" width="1416" class="common_img" src="'+R+'" style="width:800px;"><h4 id="display-information" tabindex="-1">Display Information <a class="header-anchor" href="#display-information" aria-label="Permalink to &quot;Display Information&quot;">​</a></h4><p>Display the recognized card information including, ID, position and name. Use corresponding color according to waste category.</p><img loading="lazy" height="231" width="1589" class="common_img" src="'+I+'" style="width:800px;"><p>Use cv2.putText() function to display the text on the image. Take ‘<strong>cv2.putText(image, waste_name + &quot; &quot; + str(float(cls_conf))[:4], (x1, y1 - 5), cv2.FONT_HERSHEY_SIMPLEX, 0.7, COLORS[waste_class_name], 2)</strong>’ for example.</p><p>The first parameter ‘<strong>image</strong>’ is the input image.</p><p>The second parameter ‘<strong>waste_name + &quot; &quot; + str(float(cls_conf))[:4]</strong>’ is the displayed text.</p><p>The third parameter ‘<strong>(x1, y1 - 5)</strong>’ The third parameter ‘<strong>(x1, y1 - 5)</strong>’ is the coordinate of the position where the text is displayed.</p><p>The fourth parameter ‘<strong>cv2.FONT_HERSHEY_SIMPLEX</strong>’ is the font type.</p><p>The fifth parameter ‘<strong>0.7</strong>’ is the font size.</p><p>The sixth parameter ‘<strong>COLORS[waste_class_name]</strong>’ is font color.</p><p>The seventh parameter ‘<strong>2</strong>’ is font weight.</p><p>Use <strong>cv2.rectangle()</strong> function to draw rectangle on the image. Take ‘<strong>cv2.rectangle(image, (x1, y1), (x2, y2), COLORS[waste_class_name], 3)</strong>’ for example.</p><p>The first parameter ‘<strong>image</strong>’ is the input image.</p><p>The second parameter ‘<strong>(x1, y1)</strong>’ is the coordinate of upper left corner of the rectangle.</p><p>The third parameter ‘<strong>(x2, y2)</strong>’ is the coordinate of lower right corner of the rectangle.</p><p>The fourth parameter ‘<strong>COLORS[waste_class_name]</strong>’ is the font color.</p><p>The fifth parameter ‘<strong>3</strong>’ is the width of the line</p><h4 id="transfer-sign" tabindex="-1">Transfer Sign <a class="header-anchor" href="#transfer-sign" aria-label="Permalink to &quot;Transfer Sign&quot;">​</a></h4><img loading="lazy" height="95" width="655" class="common_img" src="'+k+'" style="width:800px;"><p>If no cards are recognized, set ‘<strong>cards</strong>’ as 0. Clear transfer flag variable ‘<strong>state.count</strong>’ as None, then recognize again.</p><img loading="lazy" height="251" width="1763" class="common_img" src="'+Q+'" style="width:600px;"><p>If card is recognized but has not been recognized before, find the card with the maximum probability. Store this card as the target to be transferred.</p><img loading="lazy" height="807" width="1780" class="common_img" src="'+X+'" style="width:800px;"><p>If card is recognized and has also been recognized in last frame, find the card nearest to the camera recognized in this frame. If the distance between them is too long, set transferring flag as 0.</p><p>If the distance is appropriate, recognition is correct. JetMax Pro starts transferring after 50 times of correct recognition.</p><p>Go into child thread <strong>moving()</strong> function to let JetMax Pro suck waste card and place it to the specific position.</p><h3 id="motion-control-function" tabindex="-1">Motion Control Function <a class="header-anchor" href="#motion-control-function" aria-label="Permalink to &quot;Motion Control Function&quot;">​</a></h3><p>moving function is used to control sliding rail and robot arm to move.</p><img loading="lazy" height="1137" width="1452" class="common_img" src="'+D+'" style="width:800px;"><p>Use hiwonder.pwm_servo1.set_position() function to control PWM servo to rotate. Take ‘<strong>hiwonder.pwm_servo1.set_position(90, 0.5)</strong>’ for example.</p><p>The first parameter ‘<strong>90</strong>’ is servo angle</p><p>The second parameter ‘<strong>0.5</strong>’ is running time of servo in second.</p><p>Use ‘jetmax.set_position()’ function to control robot arm to move. Take ‘<strong>jetmax.set_position((x, y, z), 0.8)</strong>’ for example.</p><p>The first parameter ‘<strong>(x, y, z)</strong>’ is the coordinate of the end of robot arm. (x, y, z), set in global variable, is the coordinate of position where the card is placed.</p><p>The second parameter ‘<strong>0.8</strong>’ is pitch angle.</p><h2 id="_16-4-lesson-5-tag-sorting" tabindex="-1">16.4 Lesson 5 Tag Sorting <a class="header-anchor" href="#_16-4-lesson-5-tag-sorting" aria-label="Permalink to &quot;16.4 Lesson 5 Tag Sorting&quot;">​</a></h2><p>JetMax Pro recognizes the tag with its camera first, then place the tag block to specific position according to the recognized tag information and position.</p><p>AprilTag is a visual positioning tag similar to QR code or bar code.</p><p>Firstly, the program subscribes to information published by camera node to obtain real-time image data. After that, convert RGB color space to gray image. Following, read camera parameters.</p><p>Next, call AprilTag library function to detect AprilTag to get tag ID, get coordinate of four corners of the tag as well as the coordinate of the tag center.</p><p>Compute the recognized coordinate to get the coordinate of the block. Compute angle of the servo at the target position with inverse kinematics, then control robot arm to move to the target position and transfer the block to specific position according to its ID.</p><p>The source code of this program is stored in <strong>/ros/src/stepper/scripts/waste_classification_stepper.py</strong></p><img loading="lazy" height="922" width="1674" class="common_img" src="'+B+'" style="width:800px;"><h3 id="_16-4-1-operation-steps" tabindex="-1">16.4.1 <strong>Operation Steps</strong> <a class="header-anchor" href="#_16-4-1-operation-steps" aria-label="Permalink to &quot;16.4.1 **Operation Steps**&quot;">​</a></h3><ol><li><p>Start JetMax Pro, and connect your computer to WiFi generated by JetMax Pro.</p><img loading="lazy" height="234" width="359" class="common_img" src="'+E+'" style="width:800px;"></li><li><p>Connect to robot system desktop through NoMachine. Double click <img loading="lazy" height="91" width="81" class="inline-icon" src="'+e+'" alt="terminal"> to open terminal. (For how to install and use NoMachine, please refer to ‘<strong>7. Robot System Remote Connection</strong>’.) Robot system is as pictured.</p></li></ol><p><img loading="lazy" height="91" width="81" class="inline-icon" src="'+e+'" alt="terminal"><img loading="lazy" height="671" width="1267" src="'+U+'"></p><ol start="3"><li><p>Click <img loading="lazy" height="66" width="69" class="inline-icon" src="'+K+'"> or press “<strong>Ctrl+Alt+T</strong>” to open terminal.</p></li><li><p>Input command ‘<strong>cd ros/src/stepper/scripts/</strong>’ and press Enter to go to the directory where the game program is stored</p><img loading="lazy" height="26" width="554" class="common_img" src="'+V+'" style="width:600px;"></li><li><p>Input command ‘<strong>./kill_app_funcs.sh</strong>’ and press Enter to close APP auto-start service.</p><img loading="lazy" height="22" width="633" class="common_img" src="'+L+'" style="width:600px;"></li><li><p>Input command “<strong>rosrun stepper apriltag_sorting_stepper.py</strong>” to start tag sorting. It takes about 30s to start the game. Please be patient!</p><img loading="lazy" height="36" width="727" class="common_img" src="'+Y+'" style="width:600px;"></li><li><p>Input command “<strong>./restart_app_funcs.sh</strong>” to enable APP service. Do not skip this step, otherwise other games will be influenced.</p><img loading="lazy" height="21" width="645" class="common_img" src="'+G+'" style="width:600px;"></li></ol><h3 id="_16-4-2-program-outcome" tabindex="-1">16.4.2 Program Outcome <a class="header-anchor" href="#_16-4-2-program-outcome" aria-label="Permalink to &quot;16.4.2 Program Outcome&quot;">​</a></h3><p>After game starts, place tag cards within the recognition area on the map. Robot arm will place tag cards to corresponding area in order.</p><h3 id="_16-4-3-program-analysis" tabindex="-1">16.4.3 Program Analysis <a class="header-anchor" href="#_16-4-3-program-analysis" aria-label="Permalink to &quot;16.4.3 Program Analysis&quot;">​</a></h3><h3 id="import-function-library-1" tabindex="-1">Import Function Library <a class="header-anchor" href="#import-function-library-1" aria-label="Permalink to &quot;Import Function Library&quot;">​</a></h3><img loading="lazy" height="295" width="754" class="common_img" src="'+W+'" style="width:800px;"><p>Import OpenCV, time, mathematics, thread and inverse kinematics libraries. You can call functions in the library in this format, ‘library name + function name(parameter,parameter...)’.<img loading="lazy" height="42" width="637" class="inline-icon" src="'+F+'"></p><p>time.sleep (0.01) means that ‘<strong>sleep</strong>’ function in ‘<strong>time</strong>’ library is called. The function of sleep() is to delay.</p><p>There are some built-in libraries in Python, such as ‘<strong>time</strong>’, ‘<strong>cv2</strong>’ and ‘<strong>math</strong>’, and you can directly import and call the library. Or you can write a library on your own.</p><p>‘<strong>std_srvs.srv</strong>’ is a library of ros service type.</p><h3 id="define-global-variables-1" tabindex="-1">Define Global Variables <a class="header-anchor" href="#define-global-variables-1" aria-label="Permalink to &quot;Define Global Variables&quot;">​</a></h3><ol><li><p>Set the name of node</p><img loading="lazy" height="28" width="824" class="common_img" src="'+H+'" style="width:600px;"></li><li><p>Set the position where the object should be placed after sorting.</p><img loading="lazy" height="144" width="826" class="common_img" src="'+N+'" style="width:800px;"></li><li><p>Set resolution of detection image as 640x480. Set label side length to 33.3. Set initial position of sliding rail as 0.</p><img loading="lazy" height="195" width="1274" class="common_img" src="'+Z+'" style="width:600px;"><p><strong>4.3 Verify Whether to Use python3</strong></p><img loading="lazy" height="87" width="919" class="common_img" src="'+$+'" style="width:600px;"></li></ol><p>Use <strong>sys.version_info.major</strong> to read the version of Python. If it is not python3, the program will exit.</p><p><strong>4.4 ApriltagSorting</strong></p><p>Content in yellow frame defines parameters required by ApriltagSorting. Functions of ApriltagSorting all have these properties. load_camera_params() function in red frame is used to get the parameters of camera.</p><img loading="lazy" height="714" width="1426" class="common_img" src="'+tt+'" style="width:800px;"><p><strong>4.5 Convert Camera Coordinate to Real Coordinate</strong></p><img loading="lazy" height="757" width="1630" class="common_img" src="'+et+'" style="width:800px;"><p><strong>camer_to_world</strong> function is used to convert the coordinate on camera to real coordinate so as to get the real distance. The meaning of parameters of this function is as below.</p><p>Cam_mtx：</p><p>Transfer <strong>Cam_mtx</strong> to <strong>np.asmatrix.I</strong> function to get inverse matrix <strong>inv_k</strong> of cam_mtx</p><p>r：</p><p>Use <strong>np.zeros</strong> function to create empty matrix <strong>r_mat</strong>. Input <strong>r</strong> to <strong>cv2.Rodrigues</strong> function to convert vector to matrix and fill in <strong>r_mat</strong>. Then input <strong>r_mat</strong> into the <strong>np.asmatrix.I</strong> function to get the inverse matrix <strong>inv_r</strong> of <strong>r_mat</strong>.</p><p>t：</p><p>Input t into <strong>np.asmatrix</strong> to get new matrix, and input this new matrix and matrix <strong>inv_r</strong> into <strong>np.dot</strong> so as to compute the matrix <strong>transPlaneToCam</strong> required to convert coordinate.</p><p>Define the list <strong>world_pt = []</strong> used for output</p><p>Define a new matrix <strong>coords</strong></p><p>Define cyclic reading <strong>img_points</strong>, and name the content read each time <strong>img_pt</strong>, and put <strong>img_pt</strong> into corresponding empty matrix <strong>coords</strong>.</p><p>Use <strong>coords</strong> and <strong>inv_k</strong> to compute new matrix <strong>worldPtCam</strong>. Divide <strong>transPlaneToCam</strong> and <strong>worldPtCam</strong> to get the transformation coefficient <strong>scale</strong>.</p><p><strong>scale</strong> times <strong>worldPtPlane</strong> to get the transformed matrix <strong>scale_worldPtPlane</strong>.</p><p><strong>scale_worldPtPlane</strong> matrix subtracts <strong>transPlaneToCam</strong> matrix to get real coordinate <strong>worldPtPlaneReproject</strong>.</p><p>Define an empty matrix <strong>pt</strong> used to store coordinate, and assign the value of <strong>worldPtPlaneReproject</strong> to <strong>pt</strong>. Lastly, add <strong>pt</strong> to <strong>world_pt</strong>.</p><h3 id="analyze-main-function-1" tabindex="-1">Analyze Main Function <a class="header-anchor" href="#analyze-main-function-1" aria-label="Permalink to &quot;Analyze Main Function&quot;">​</a></h3><p>In python, ‘<strong>__name__ == ’__main__:’</strong>’ is main function of the program. The program firstly call <strong>rospy.init_node()</strong> function, and initialize node with ros. Initialization configuration includes ports, external devices, and timed interrupts, which are completed during initialization.</p><img loading="lazy" height="413" width="1268" class="common_img" src="'+ot+'" style="width:600px;"><p>Robot arm and sliding rail recover initial posture. Set sliding mode.</p><img loading="lazy" height="207" width="863" class="common_img" src="'+at+'" style="width:800px;"><h4 id="instantiate-1" tabindex="-1">Instantiate <a class="header-anchor" href="#instantiate-1" aria-label="Permalink to &quot;Instantiate&quot;">​</a></h4><img loading="lazy" height="230" width="1039" class="common_img" src="'+nt+'" style="width:800px;"><h4 id="as-names-of-some-function-libraries-are-too-long-you-can-instantiate-the-function-library-making-it-convenient-to-call-functions-after-instantiation-you-can-directly-call-function-in-this-way-jetmax-function-name-parameter-parameter" tabindex="-1">As names of some function libraries are too long, you can instantiate the function library making it convenient to call functions. After instantiation, you can directly call function in this way, ‘jetmax.function name(parameter, parameter...)’ <a class="header-anchor" href="#as-names-of-some-function-libraries-are-too-long-you-can-instantiate-the-function-library-making-it-convenient-to-call-functions-after-instantiation-you-can-directly-call-function-in-this-way-jetmax-function-name-parameter-parameter" aria-label="Permalink to &quot;As names of some function libraries are too long, you can instantiate the function library making it convenient to call functions. After instantiation, you can directly call function in this way, ‘jetmax.function name(parameter, parameter...)’&quot;">​</a></h4><h3 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h3><h4 id="publish-and-subscribe-to-topic-1" tabindex="-1">Publish and Subscribe to Topic <a class="header-anchor" href="#publish-and-subscribe-to-topic-1" aria-label="Permalink to &quot;Publish and Subscribe to Topic&quot;">​</a></h4><p>Subscribe to function that processes image</p><img loading="lazy" height="100" width="1788" class="common_img" src="'+rt+'" style="width:600px;"><h3 id="process-and-analyze-image-1" tabindex="-1">Process and Analyze Image <a class="header-anchor" href="#process-and-analyze-image-1" aria-label="Permalink to &quot;Process and Analyze Image&quot;">​</a></h3><h4 id="convert-to-gray-image" tabindex="-1">Convert to Gray Image <a class="header-anchor" href="#convert-to-gray-image" aria-label="Permalink to &quot;Convert to Gray Image&quot;">​</a></h4><p>Call ‘<strong>cv2.cvtColor</strong>’ function to process image. Convert RGB image to gray image.</p><img loading="lazy" height="52" width="1561" class="common_img" src="'+st+'" style="width:600px;"><p>The first parameter ‘<strong>np.copy(img)</strong>’ represents the picture to be converted</p><p>The second parameter ‘<strong>cv2.COLOR_RGB2GRAY</strong>’ represents convert RGB image to gray image. ‘<strong>cv2.COLOR_BGR2RGB</strong>’ represents convert BGR format to RGB format.</p><h4 id="recognize-and-display" tabindex="-1">Recognize and Display <a class="header-anchor" href="#recognize-and-display" aria-label="Permalink to &quot;Recognize and Display&quot;">​</a></h4><p>Call ‘<strong>at_detector.detect</strong>’ function to detect AprilTag on the obtained image. Get the coordinate of four corners and coordinate of tag center. This program is as follow.</p><img loading="lazy" height="182" width="1421" class="common_img" src="'+it+'" style="width:600px;"><p>‘<strong>frame_gray</strong>’ represents the image to be detected</p><h4 id="frame-apriltag" tabindex="-1">Frame AprilTag <a class="header-anchor" href="#frame-apriltag" aria-label="Permalink to &quot;Frame AprilTag&quot;">​</a></h4><p>After AprilTag is found, program will frame it. The program is as followed.</p><img loading="lazy" height="274" width="1609" class="common_img" src="'+lt+'" style="width:600px;"><ol><li>Use ‘<strong>cv2.drawContours</strong>’ function to draw the contour of tag.</li></ol><p>The first parameter ‘<strong>img</strong>’ represents the specific tag image whose contour will be drawn.</p><p>The second parameter ‘<strong>corners</strong>’ refers to the contour itself</p><p>The third parameter ‘<strong>-1</strong>’ represents index of contour. ‘-1’ represents draw all contours.</p><p>The fourth parameter ‘<strong>(255, 0, 0)</strong>’ represents the color of contour. Three values in the bracket range from 0 to 255. Contour color is mixed by red, green and blue. The first value ‘255’ represents value of red, the second value ‘0’ represents value of green, and the third value represents value of blue.</p><p>The fifth parameter ‘<strong>3</strong>’ represents the width of contour.</p><ol start="2"><li>Use ‘<strong>cv2.circle</strong>’ function to draw the center of the tag</li></ol><p>The first parameter ‘<strong>img</strong>’ represents the specific tag image whose center to be drawn.</p><p>The second parameter ‘<strong>tuple(center)</strong>’ represents the coordinate of center of the drawn circle which is determined by the detected object.</p><p>The third parameter ‘<strong>5</strong>’ represents the radius of the drawn circle.</p><p>The fourth parameter ‘<strong>(255, 255, 0)</strong>’ represents the color of the drawn circle. You can set this parameter in the same way as setting parameter 4 of drawing the contour of tag</p><p>The fifth parameter ‘<strong>10</strong>’ represents the width. The greater the value, the wider the border of circle.</p><h4 id="information-feedback" tabindex="-1">Information Feedback <a class="header-anchor" href="#information-feedback" aria-label="Permalink to &quot;Information Feedback&quot;">​</a></h4><p>After tag is recognized, VNC software gives following feedback.</p><p>Program will draw 2 straight lines with ‘<strong>cv2.line</strong>’ function. The intersection corresponds to image center.</p><img loading="lazy" height="59" width="1734" class="common_img" src="'+ct+'" style="width:600px;" alt="1"><p>Take ‘<strong>cv2.line(img, (int(img_w / 2), int(img_h / 2 - 10)), (int(img_w / 2), int(img_h / 2 + 10)), (0, 255, 255), 2)</strong>’ for example.</p><p>The first parameter ‘<strong>img</strong>’ represents the specific image</p><p>The second parameter ‘<strong>(int(img_w / 2), int(img_h / 2 - 10))</strong>’ represents the coordinate of the start of straight line</p><p>The third parameter ‘<strong>(int(img_w / 2), int(img_h / 2 + 10))</strong>’ represents the coordinate of the end of straight line</p><p>The fourth parameter ‘<strong>(0, 255, 255)</strong>’ refers to color of straight line. You can set this parameter in the same way as setting parameter 4 of ‘<strong>frame AprilTag</strong>’</p><p>The fifth parameter ‘<strong>2</strong>’ represents the line width.</p><ol><li>The program uses ‘<strong>print</strong>’ function to display tag ID and coordinate of tag center as pictured.</li></ol><img loading="lazy" height="33" width="1271" class="common_img" src="'+gt+'" style="width:600px;" alt="2"><p>The first parameter ‘<strong>tag.tag_id</strong>’ represents tag ID</p><p>The second parameter ‘<strong>center[0]</strong>’ represents X-axis coordinate of tag center</p><p>The third parameter ‘<strong>center[1]</strong>’ represents Y-axis coordinate of tag center</p><h3 id="motion-control-function-1" tabindex="-1">Motion Control Function <a class="header-anchor" href="#motion-control-function-1" aria-label="Permalink to &quot;Motion Control Function&quot;">​</a></h3><p>moving function is used to control movement. Content in red frame is used to call camera parameter and compute Euler angle.</p><img loading="lazy" height="1775" width="1245" class="common_img" src="'+pt+'" style="width:800px;"><p>Use <strong>hiwonder.pwm_servo1.set_position()</strong> function to control PWM servo to rotate. Take ‘<strong>hiwonder.pwm_servo1.set_position(90, 0.5)</strong>’ for example.</p><p>The first parameter ‘<strong>90</strong>’ is servo angle</p><p>The second parameter ‘<strong>0.5</strong>’ is running time in second.</p><p>Use jetmax.set_position() function to control robot arm to move. Take ‘<strong>jetmax.set_position((x, y, z), 0.8)</strong>’ for example.</p><p>The first parameter ‘<strong>(x, y, z)</strong>’ is coordinate of the end of robot arm. (x, y, z), set in global variable, is the coordinate of position where the card is placed.</p><p>The second parameter ‘<strong>0.8</strong>’ is pitch angle.</p>',242)])])}const At=o(mt,[["render",dt]]);export{xt as __pageData,At as default};
